# Docstrings y recursión
def factorial(n):
    """Calcula n! de forma recursiva."""
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def fibonacci(n):
    """Devuelve el n-ésimo número de Fibonacci."""
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

print(factorial(6))
